// RECONCILIATION — prompt 56 pre-flight.
//
// scratchpad/p55-carried-dm2-d24.mjs resolved [DM-2] by patching the ARTEFACT
// adapters/pdf/maps/433d.map.json. That file is GENERATED by
// scratchpad/p54-433d-author-map.mjs, which carries its own `_carried` block, so the patch put
// the artefact out of agreement with its generator and `npm run sweeps:deep` has been failing
// ever since with "433d.map.json does not match what re-derivation produces".
//
// The fix is to move the resolution INTO THE GENERATOR, which is where every other byte of that
// file comes from. This script splices the artefact's own `_carried` object into the generator
// source, so re-derivation produces exactly what is committed.
//
// It patches BY LINE, never by matching a quoted blob: an escaped quote inside a heredoc has
// twice failed to match in this tree, and a patch that silently matches nothing reports success.
// The splice boundaries are found by brace depth from the `_carried: {` line, and the script
// ASSERTS ITS OWN OUTPUT ON DISK before it exits.
import { readFileSync, writeFileSync } from 'node:fs';

const GEN = 'scratchpad/p54-433d-author-map.mjs';
const MAP = 'adapters/pdf/maps/433d.map.json';

const carried = JSON.parse(readFileSync(MAP, 'utf8'))._carried;
const src = readFileSync(GEN, 'utf8');
const lines = src.split('\n');

const start = lines.findIndex((l) => l.trim() === '_carried: {');
if (start < 0) { console.error(`no "_carried: {" line in ${GEN}`); process.exit(2); }

let depth = 0, end = -1;
for (let i = start; i < lines.length; i++) {
  for (const ch of lines[i]) { if (ch === '{') depth++; else if (ch === '}') depth--; }
  if (depth === 0) { end = i; break; }
}
if (end < 0) { console.error(`the "_carried" object in ${GEN} does not close`); process.exit(2); }

const indent = lines[start].slice(0, lines[start].indexOf('_carried'));
// Serialised as JSON rather than in the surrounding literal's single-quoted idiom. That is a
// DELIBERATE and declared style deviation: the block carries long prose with apostrophes in it,
// and hand-quoting it is the exact authoring path that has eaten characters in this tree before.
// JSON is valid JS, it round-trips, and the generator emits JSON.stringify anyway — so the bytes
// this produces are provably the bytes on disk, which is the property that matters here.
const body = JSON.stringify(carried, null, 1)
  .split('\n')
  .map((l, i) => (i === 0 ? l : indent + l))
  .join('\n');

lines.splice(start, end - start + 1, `${indent}_carried: ${body},`);
const out = lines.join('\n');
writeFileSync(GEN, out);

// ASSERT THE OUTPUT REACHED DISK AS WRITTEN.
const back = readFileSync(GEN, 'utf8');
if (back !== out) { console.error(`${GEN} on disk is not what this script wrote.`); process.exit(2); }
const reparsed = back.split('\n').findIndex((l) => l.trim().startsWith('_carried: {'));
if (reparsed < 0) { console.error(`${GEN} no longer carries a _carried block after the splice.`); process.exit(2); }
console.log(`patched ${GEN} — _carried spliced from ${MAP}: ${carried.open.length} open, ${carried.resolved.length} resolved.`);
console.log('Now run: node scratchpad/p54-433d-author-map.mjs --check');
